import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"阅读指南","description":"AI Memory Handbook 阅读指南：按角色与目标选择阅读路径，了解本书的写作约定与数据口径。","frontmatter":{"title":"阅读指南","description":"AI Memory Handbook 阅读指南：按角色与目标选择阅读路径，了解本书的写作约定与数据口径。"},"headers":[],"relativePath":"reading-guide.md","filePath":"reading-guide.md","lastUpdated":1793361704000}'),o={name:"reading-guide.md"};function h(n,a,i,s,c,f){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="阅读指南" tabindex="-1">阅读指南 <a class="header-anchor" href="#阅读指南" aria-label="Permalink to &quot;阅读指南&quot;">​</a></h1><p>本书 7 篇 23 章，不需要从第一页读到最后一页。不同角色关心的问题不同，下面给出四条按角色划分的路径，以及三条按目标划分的路径。</p><h2 id="按角色选择" tabindex="-1">按角色选择 <a class="header-anchor" href="#按角色选择" aria-label="Permalink to &quot;按角色选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>读者</th><th>建议关注</th><th>你将获得</th></tr></thead><tbody><tr><td>Agent / AI 应用开发者</td><td><a href="/02-build/04-写入-抽取分型与冲突消解">构建篇</a>、<a href="/03-run/08-部署形态-本地优先的真实边界">运行篇</a>、<a href="/05-optimization/16-基准-可复现的方法学">调优篇</a></td><td>掌握单遍写入、冲突消解、多信号检索、渐进式披露、MCP 接入等核心工程方法</td></tr><tr><td>架构师与平台工程师</td><td><a href="/01-architecture/01-记忆为什么成为一等原语">架构篇</a>、<a href="/03-run/08-部署形态-本地优先的真实边界">运行篇</a>、<a href="/04-governance/12-可审计性-哈希链来源追溯与证据链">治理篇</a></td><td>建立从存储引擎到治理底座的完整架构视图，形成可扩展的记忆基础设施设计</td></tr><tr><td>技术负责人和研发管理者</td><td><a href="/01-architecture/01-记忆为什么成为一等原语">架构篇</a>、<a href="/04-governance/12-可审计性-哈希链来源追溯与证据链">治理篇</a>、<a href="/06-case-study/20-第一梯队系统深度对照">实践篇</a></td><td>判断记忆系统的成熟度、选型边界、投入边界与生产风险</td></tr><tr><td>产品与业务负责人</td><td><a href="/00-preface/2026记忆系统技术观察">技术观察</a>、<a href="/01-architecture/01-记忆为什么成为一等原语">架构篇</a>、<a href="/06-case-study/20-第一梯队系统深度对照">实践篇</a></td><td>理解不同场景对记忆的期待与恐惧，以及从「记住」走向「被信任」的产品条件</td></tr><tr><td>安全、质量与运维人员</td><td><a href="/03-run/08-部署形态-本地优先的真实边界">运行篇</a>、<a href="/04-governance/12-可审计性-哈希链来源追溯与证据链">治理篇</a>、<a href="/05-optimization/16-基准-可复现的方法学">调优篇</a></td><td>建立可观测、哈希链审计、级联删除、上线验证与故障归因机制</td></tr><tr><td>研究者与生态贡献者</td><td>全书与<a href="/06-case-study/20-第一梯队系统深度对照">实践篇</a></td><td>了解企业一线问题、工程抽象和开放议题</td></tr></tbody></table><h2 id="按目标选择" tabindex="-1">按目标选择 <a class="header-anchor" href="#按目标选择" aria-label="Permalink to &quot;按目标选择&quot;">​</a></h2><p><strong>第一次系统了解 AI 记忆</strong>：<a href="/00-preface/2026记忆系统技术观察">技术观察</a> → <a href="/01-architecture/01-记忆为什么成为一等原语">第 1 章</a> → <a href="/01-architecture/02-记忆系统参考架构">第 2 章</a> → <a href="/02-build/04-写入-抽取分型与冲突消解">第 4 章</a> → <a href="/02-build/06-检索-多信号融合与预算控制">第 6 章</a> → <a href="/06-case-study/20-第一梯队系统深度对照">第 20 章</a></p><p><strong>正在把记忆接入生产</strong>：<a href="/03-run/08-部署形态-本地优先的真实边界">第 8 章</a> → <a href="/03-run/11-规模化运营-成本延迟与容量">第 11 章</a> → <a href="/04-governance/12-可审计性-哈希链来源追溯与证据链">第 12 章</a> → <a href="/04-governance/14-写入前安全-公证注入与凭据防护">第 14 章</a> → <a href="/05-optimization/18-记忆质量度量与Badcase闭环">第 18 章</a></p><p><strong>负责选型或项目立项</strong>：<a href="/00-preface/2026记忆系统技术观察">技术观察</a> → <a href="/01-architecture/01-记忆为什么成为一等原语">第 1 章</a> → <a href="/01-architecture/03-形态与成熟度-L1-L4分级">第 3 章</a> → <a href="/06-case-study/20-第一梯队系统深度对照">第 20 章</a> → <a href="/06-case-study/21-选型决策与迁移路径">第 21 章</a> → <a href="/07-conclusion/23-未解问题与2027路线图">第 23 章</a></p><h2 id="写作约定" tabindex="-1">写作约定 <a class="header-anchor" href="#写作约定" aria-label="Permalink to &quot;写作约定&quot;">​</a></h2><p><strong>章节结构。</strong> 每章开头 3–5 段不加小标题，从一个具体的失效场景切入，说明它在概念上属于什么问题、现有做法的边界在哪、本章沿什么顺序展开。每章末尾固定有「本章小结」，内容不是复述，而是回答：本章确立了哪几条判断、各自成立的条件是什么、在什么条件下会失效。</p><p><strong>判断的形式。</strong> 书中的每条判断都尽量配三样东西：一个具体的失效场景、一段机制解释、一个使用判据。缺少场景的判断是口号，缺少机制的解释是结论，缺少判据的建议无法落地。</p><p><strong>代价必提。</strong> 每处优势描述后紧跟代价。书中不出现「唯一」「业界领先」「革命性」这类表述。</p><h2 id="数据与事实口径" tabindex="-1">数据与事实口径 <a class="header-anchor" href="#数据与事实口径" aria-label="Permalink to &quot;数据与事实口径&quot;">​</a></h2><p>本书对事实的处理遵循三条规则。</p><p><strong>第一，所有数字都标注口径与时间。</strong> 基准分数标注数据集版本、judge 类型与是否完整运行；价格标注币种与生效时间；论文标注 arXiv 编号。没有口径的数字不出现。</p><p><strong>第二，无法核验的论断一律删除，而不是弱化表述。</strong> 本书不写「据传」「业内普遍认为」这类无法追溯来源的判断。少数必须提及但证据不足的内容，会明确写出「截至 2026 年 10 月的公开文档中未见说明」。</p><p><strong>第三，对自家实现与对竞品采用同一套审慎标准。</strong> 书中对 Mnemosyne OS 的描述同样标注边界与代价，包括其基准分数尚未由仓库内一次完整运行独立复算这一事实（见<a href="/05-optimization/16-基准-可复现的方法学">第 16 章</a>）。对竞品的描述只写其边界，不写其弱点。</p><h2 id="术语" tabindex="-1">术语 <a class="header-anchor" href="#术语" aria-label="Permalink to &quot;术语&quot;">​</a></h2><p>书中出现的专有术语，在首次出现时给出中文与英文全称，之后统一使用缩写。完整对照见<a href="/00-preface/附录A-术语表">附录 A 术语表</a>，其中「易混淆点」一列列出了最容易混用的概念对，例如「删除」与「遗忘」、「哈希链审计账本」与「操作日志」、「作用域」与「命名空间」。</p><h2 id="引用与复现" tabindex="-1">引用与复现 <a class="header-anchor" href="#引用与复现" aria-label="Permalink to &quot;引用与复现&quot;">​</a></h2><p>附录 B 列出了全部可复现资源的入口，包括论文的 arXiv 编号、产品的官方文档地址、以及可被任何人复算的检索式。读者若发现书中某个数字与原始来源不符，请以原始来源为准。</p>',21)])])}const l=t(o,[["render",h]]);export{u as __pageData,l as default};
